def split_legacy_messages(apps, schema_editor):
    """Eski xabarlar: admin (staff) yozmagan shaxsiy xabarlar - ish jarayoni
    bildirishnomalari; foydalanuvchi oldin ko'rgan xabarlar o'qilgan bo'lib qoladi."""
    AdminMessage = apps.get_model("app", "AdminMessage")
    for message in AdminMessage.objects.filter(recipient__isnull=False).select_related("sender__account", "recipient"):
        sender_account = message.sender.account if message.sender_id else None
        message.is_system = not (sender_account and sender_account.is_staff)
        last_read = message.recipient.messages_last_read_at
        if last_read and message.created_at <= last_read:
            message.read_at = last_read
        message.save(update_fields=["is_system", "read_at"])


